```javascript
import {
  Group,
  Mesh,
  Shape,
  ShapeGeometry,
  Vector3,
  DirectionalLight,
  AmbientLight,
  Color,
  DoubleSide,
  FrontSide,
} from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, float, uniform, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const cleanupFns = [];
  let masterTimeline = gsap.timeline({ paused: true });

  // --- helpers ---
  function hexToVec3(hex) {
    const c = new Color(hex);
    return vec3(float(c.r), float(c.g), float(c.b));
  }

  function createRoundedRectGeometry(w, h, r) {
    const shape = new Shape();
    shape.moveTo(-w / 2 + r, -h / 2);
    shape.lineTo(w / 2 - r, -h / 2);
    shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
    shape.lineTo(w / 2, h / 2 - r);
    shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
    shape.lineTo(-w / 2 + r, h / 2);
    shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
    shape.lineTo(-w / 2, -h / 2 + r);
    shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);
    return new ShapeGeometry(shape);
  }

  // --- material factory ---
  function createTileMaterial() {
    const mat = new MeshStandardNodeMaterial({
      side: DoubleSide,
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
      clearcoatRoughness: 0.3,
      anisotropy: 0.6,
      anisotropyRotation: 0, // along x
    });
    // vertical gradient bottom (#1a1a22) to top (#121218)
    const color1 = hexToVec3(0x1a1a22);
    const color2 = hexToVec3(0x121218);
    mat.colorNode = mix(color1, color2, uv.y);
    mat.needsUpdate = true;
    return mat;
  }

  // --- data ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const brandTexts = [
    'HODINKEE',
    'MONOCLE',
    'WALLPAPER',
    'ESQUIRE',
    'WIRED',
    'FINANCIAL TIMES',
  ];
  const kickerText = 'AS FEATURED IN';
  const kickerFontSize = 9; // scene-units (as per spec)
  const brandFontSize = 13;

  // --- kicker ---
  const kicker = ctx.fontAtlas.createText(kickerText, {
    fontSize: kickerFontSize,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 12, // 0.12em ≈ 12% of 9≈1.08px? Use 12 for emphasis
  });
  // The text mesh might be a group with one or more meshes; set opacity via traverse
  kicker.traverse((child) => {
    if (child.isMesh && child.material) {
      child.material.opacity = 0.78;
      child.material.transparent = true;
    }
  });
  kicker.position.set(0, 0.745 + 0.3 + 0.31, 0.01); // above top row (top row y=0.435, tile half=0.31 -> 0.745; + 0.3 gap)
  group.add(kicker);
  cleanupFns.push(() => {
    kicker.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  });

  // --- tiles ---
  const tileWidth = 1.0;
  const tileHeight = 0.62;
  const gap = 0.25;
  const cornerRadius = 0.02;
  const gridW = 3 * tileWidth + 2 * gap; // 3.5
  const gridH = 2 * tileHeight + gap; // 1.49
  const startX = -gridW / 2 + tileWidth / 2; // -1.25
  const startY = gridH / 2 - tileHeight / 2; // 0.435
  const tiles = [];
  const brandMeshes = [];

  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 3; col++) {
      const idx = row * 3 + col;
      const x = startX + col * (tileWidth + gap);
      const y = row === 0 ? startY : -startY;

      // tile mesh
      const geo = createRoundedRectGeometry(tileWidth, tileHeight, cornerRadius);
      const mat = createTileMaterial();
      const tile = new Mesh(geo, mat);
      tile.position.set(x, y, 0);
      tile.castShadow = true;
      tile.receiveShadow = true;
      tile.userData.isTile = true;
      group.add(tile);
      tiles.push(tile);
      cleanupFns.push(() => {
        geo.dispose();
        mat.dispose();
      });

      // brand text
      const brand = ctx.fontAtlas.createText(brandTexts[idx], {
        fontSize: brandFontSize,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: 8, // 0.08em ≈ 8% of 13≈1.04px
      });
      brand.traverse((child) => {
        if (child.isMesh && child.material) {
          child.material.opacity = 0.78;
          child.material.transparent = true;
        }
      });
      brand.position.set(0, 0, 0.01); // slightly in front of tile
      tile.add(brand);
      brandMeshes.push(brand);
      cleanupFns.push(() => {
        brand.traverse((child) => {
          if (child.geometry) child.geometry.dispose();
          if (child.material) child.material.dispose();
        });
      });
    }
  }

  // --- lights ---
  // key light raking at 35° elevation
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1, Math.tan(35 * Math.PI / 180), 1).normalize();
  group.add(keyLight);

  const rimLight = new DirectionalLight(0xe8ecf2, 0.8);
  rimLight.position.set(-1, -0.5, -1).normalize();
  group.add(rimLight);

  const ambient = new AmbientLight(0x16161d, 0.6);
  group.add(ambient);

  // optional fill
  const fillLight = new DirectionalLight(0xffffff, 0.3);
  fillLight.position.set(0, 0, 1);
  group.add(fillLight);

  cleanupFns.push(() => {
    keyLight.dispose && keyLight.dispose();
    rimLight.dispose && rimLight.dispose();
    ambient.dispose && ambient.dispose();
    fillLight.dispose && fillLight.dispose();
  });

  // --- entrance animation (stagger-cards) ---
  tiles.forEach((tile, i) => {
    // initial state
    tile.material.opacity = 0;
    tile.material.transparent = true;
    tile.position.y = tile.position.y + 0.2; // offset for fade-up
    tile.userData.origY = tile.position.y - 0.2;

    masterTimeline.to(tile.position, {
      y: tile.userData.origY,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, i * 0.08);
    masterTimeline.to(tile.material, {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, i * 0.08);
  });

  // also animate kicker (no stagger)
  kicker.material = kicker.material || (kicker.children[0] && kicker.children[0].material);
  if (kicker.material) {
    kicker.material.opacity = 0;
    kicker.material.transparent = true;
    masterTimeline.to(kicker.material, { opacity: 0.78, duration: 0.5, ease: 'power2.out' }, 0);
    masterTimeline.to(kicker.position, { y: kicker.position.y, duration: 0.5, ease: 'power2.out' }, 0);
    // hack: set initial offset to match fade-up
    kicker.position.y -= 0.2;
    masterTimeline.to(kicker.position, { y: kicker.position.y + 0.2, duration: 0.5, ease: 'power2.out' }, 0);
  }

  masterTimeline.play();

  // --- hover interactions ---
  tiles.forEach((tile, idx) => {
    const brand = brandMeshes[idx];
    tile.userData.handlers = {
      pointerover: () => {
        gsap.to(tile.position, { z: 0.05, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        brand.traverse((child) => {
          if (child.isMesh && child.material) {
            gsap.to(child.material, { opacity: 1, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
          }
        });
      },
      pointerout: () => {
        gsap.to(tile.position, { z: 0, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        brand.traverse((child) => {
          if (child.isMesh && child.material) {
            gsap.to(child.material, { opacity: 0.78, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
          }
        });
      },
    };
  });

  // --- cleanup ---
  group.userData.cleanup = () => {
    masterTimeline.kill();
    cleanupFns.forEach(fn => fn());
    // also kill any gsap tweens on elements
    gsap.killTweensOf(tiles);
    gsap.killTweensOf(brandMeshes);
    gsap.killTweensOf(kicker);
  };

  return group;
}
